const body = $json.body || {};

const website = body.website;

if (!website) {
  throw new Error("Website URL is required");
}

const defaultICP = {
  industries: ["Technology", "Software", "SaaS"],
  companySizes: ["Startup", "Small", "Mid-size", "Enterprise"],
  locations: ["USA", "United States", "India", "UK", "Canada"],
  businessModels: ["B2B", "Subscription-based", "SaaS"],
  technologies: ["AWS", "Docker", "Kubernetes", "Python", "JavaScript"]
};

const userICP = body.icp || {};

return [
  {
    json: {
      website: website.trim(),

      icp: {
        industries: userICP.industries || defaultICP.industries,
        companySizes: userICP.companySizes || defaultICP.companySizes,
        locations: userICP.locations || defaultICP.locations,
        businessModels: userICP.businessModels || defaultICP.businessModels,
        technologies: userICP.technologies || defaultICP.technologies
      }
    }
  }
];

const website = $json.website;

if (!website) {
  throw new Error("Website URL is required");
}

let url = website.trim();

if (!/^https?:\/\//i.test(url)) {
  url = "https://" + url;
}

// Extract hostname without using the URL constructor
let domain = url
  .replace(/^https?:\/\//i, "")
  .split("/")[0]
  .split("?")[0]
  .split("#")[0]
  .replace(/^www\./i, "");

if (!domain) {
  throw new Error("Could not extract domain");
}

return [
  {
    json: {
      website: url,
      domain: domain
    }
  }
];

const data = $json.data;

if (!data) {
  throw new Error("No website content received");
}

const content = data
  .replace(/\n{3,}/g, "\n\n")
  .trim();

const website = $('Code in JavaScript1').first().json.website;
const domain = $('Code in JavaScript1').first().json.domain;

return [
  {
    json: {
      website,
      domain,
      content,
      contentLength: content.length
    }
  }
];

const response = $json.choices?.[0]?.message?.content;

if (!response) {
  throw new Error("No Groq AI response received");
}

let analysis;

try {
  analysis = JSON.parse(response);
} catch (error) {
  const match = response.match(/\{[\s\S]*\}/);

  if (!match) {
    throw new Error("Groq response is not valid JSON");
  }

  try {
    analysis = JSON.parse(match[0]);
  } catch (parseError) {
    throw new Error("Could not parse Groq JSON response");
  }
}

return [
  {
    json: {
      success: true,
      analysis: analysis
    }
  }
];

const analysis = $json.analysis;

if (!analysis) {
  throw new Error("No company analysis found");
}

// ======================================
// ICP CONFIGURATION
// ======================================

const defaultICP = {
  industries: ["Technology", "Software", "SaaS"],
  companySizes: ["Startup", "Small", "Mid-size", "Enterprise"],
  locations: ["USA", "United States", "India", "UK", "Canada"],
  businessModels: ["B2B", "Subscription-based", "SaaS"],
  technologies: [
    "AWS",
    "Docker",
    "Kubernetes",
    "Python",
    "JavaScript"
  ]
};

const ICP = {
  industries: $json.icp?.industries || defaultICP.industries,

  companySizes:
    $json.icp?.companySizes || defaultICP.companySizes,

  locations:
    $json.icp?.locations || defaultICP.locations,

  businessModels:
    $json.icp?.businessModels || defaultICP.businessModels,

  technologies:
    $json.icp?.technologies || defaultICP.technologies
};

// ======================================
// HELPER
// ======================================

function matchesICP(value, allowedValues) {
  if (!value || !Array.isArray(allowedValues)) {
    return false;
  }

  const text = String(value).toLowerCase();

  return allowedValues.some(item =>
    text.includes(String(item).toLowerCase())
  );
}

// ======================================
// INITIALIZE
// ======================================

let score = 0;

const breakdown = {
  industry: 0,
  company_size: 0,
  geography: 0,
  revenue: 0,
  technology: 0,
  growth: 0,
  business_model: 0
};

const reasons = [];
const matchedCriteria = [];
const missingCriteria = [];

// ======================================
// INDUSTRY — 25
// ======================================

if (analysis.industry) {

  if (matchesICP(analysis.industry, ICP.industries)) {

    breakdown.industry = 25;
    score += 25;

    matchedCriteria.push("Industry");

    reasons.push(
      "Industry matches the ICP"
    );

  } else {

    missingCriteria.push("Industry");
  }

} else {

  missingCriteria.push(
    "Industry — Unknown"
  );
}

// ======================================
// COMPANY SIZE — 20
// ======================================

if (analysis.company_size) {

  if (
    matchesICP(
      analysis.company_size,
      ICP.companySizes
    )
  ) {

    breakdown.company_size = 20;
    score += 20;

    matchedCriteria.push("Company Size");

    reasons.push(
      "Company size fits the ICP"
    );

  } else {

    missingCriteria.push("Company Size");
  }

} else {

  missingCriteria.push(
    "Company Size — Unknown"
  );
}

// ======================================
// GEOGRAPHY — 15
// ======================================

if (analysis.location) {

  if (
    matchesICP(
      analysis.location,
      ICP.locations
    )
  ) {

    breakdown.geography = 15;
    score += 15;

    matchedCriteria.push("Geography");

    reasons.push(
      "Geography matches the ICP"
    );

  } else {

    missingCriteria.push("Geography");
  }

} else {

  missingCriteria.push(
    "Geography — Unknown"
  );
}

// ======================================
// REVENUE — 15
// ======================================

// Revenue is not currently available
// from our enrichment sources.

breakdown.revenue = 0;

missingCriteria.push(
  "Revenue — Unknown"
);

// ======================================
// TECHNOLOGY — 10
// ======================================

if (
  Array.isArray(analysis.technologies) &&
  analysis.technologies.length > 0
) {

  const companyTechnologies =
    analysis.technologies.map(
      x => String(x).toLowerCase()
    );

  const matchedTechnologies =
    ICP.technologies.filter(
      expected =>
        companyTechnologies.some(
          actual =>
            actual.includes(
              String(expected).toLowerCase()
            )
        )
    );

  if (matchedTechnologies.length > 0) {

    breakdown.technology = 10;
    score += 10;

    matchedCriteria.push(
      "Technology Stack"
    );

    reasons.push(
      `Technology match: ${matchedTechnologies.join(", ")}`
    );

  } else {

    missingCriteria.push(
      "Technology Stack"
    );
  }

} else {

  missingCriteria.push(
    "Technology Stack — Unknown"
  );
}

// ======================================
// GROWTH — 10
// ======================================

if (
  Array.isArray(analysis.growth_signals) &&
  analysis.growth_signals.length > 0
) {

  breakdown.growth = 10;
  score += 10;

  matchedCriteria.push(
    "Growth"
  );

  reasons.push(
    "Positive growth signals detected"
  );

} else {

  missingCriteria.push(
    "Growth — No supported signals"
  );
}

// ======================================
// BUSINESS MODEL — 5
// ======================================

if (analysis.business_model) {

  if (
    matchesICP(
      analysis.business_model,
      ICP.businessModels
    )
  ) {

    breakdown.business_model = 5;
    score += 5;

    matchedCriteria.push(
      "Business Model"
    );

    reasons.push(
      "Business model fits the ICP"
    );

  } else {

    missingCriteria.push(
      "Business Model"
    );
  }

} else {

  missingCriteria.push(
    "Business Model — Unknown"
  );
}

// ======================================
// FIT LEVEL
// ======================================

let fit;

if (score >= 80) {

  fit = "High Fit";

} else if (score >= 60) {

  fit = "Medium Fit";

} else {

  fit = "Low Fit";
}

// ======================================
// FINAL OUTPUT
// ======================================

return [
  {
    json: {

      ...$json,

      success: true,

      company:
        analysis.company_name,

      score: score,

      fit: fit,

      breakdown: breakdown,

      reasons: reasons,

      matched_criteria:
        matchedCriteria,

      missing_criteria:
        missingCriteria,

      icp_used: ICP
    }
  }
];

const html = ($json.data || "").toLowerCase();

// Get the original merged data
const merged = $('Merge').first().json;

const technologies = [];

const patterns = {
  "Microsoft Azure": ["azure", "azureedge.net", "azurewebsites.net"],
  "Microsoft Clarity": ["clarity.ms"],
  "Google Analytics": [
    "google-analytics.com",
    "googletagmanager.com",
    "gtag("
  ],
  "Google Tag Manager": ["googletagmanager.com"],
  "Cloudflare": ["cloudflare", "cdnjs.cloudflare.com"],
  "React": ["react", "react-dom"],
  "Next.js": ["_next/", "next.js"],
  "WordPress": ["wp-content", "wp-includes", "wordpress"],
  "Bootstrap": ["bootstrap.css", "bootstrap.min.css"],
  "jQuery": ["jquery.js", "jquery.min.js", "jquery("],
  "Tailwind CSS": ["tailwindcss"],
  "Microsoft 365": ["microsoft365", "office.com"]
};

for (const [technology, signatures] of Object.entries(patterns)) {
  if (signatures.some(signature => html.includes(signature))) {
    technologies.push(technology);
  }
}

return [
  {
    json: {
      ...merged,
      technologies: [...new Set(technologies)],
      technology_count: technologies.length
    }
  }
];

const xml = $json.data || "";

if (!xml) {
  return [{
    json: {
      ...$("Technology Parser").first().json,
      news: [],
      news_count: 0,
      news_summary_text: ""
    }
  }];
}

const items = xml.match(/<item>[\s\S]*?<\/item>/gi) || [];

const previous = $("Technology Parser").first().json;

// Company/domain we're searching for
const domain = String(previous.domain || "")
  .toLowerCase()
  .replace(/^www\./, "");

const companyKeywords = domain
  .split(".")[0]
  .toLowerCase();

function clean(value) {
  if (!value) return "";

  return value
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, "$1")
    .replace(/<[^>]*>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function getTag(item, tag) {
  const match = item.match(
    new RegExp(
      `<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`,
      "i"
    )
  );

  return match ? clean(match[1]) : "";
}

// ======================================
// PARSE NEWS
// ======================================

const parsedNews = items.map(item => ({
  title: getTag(item, "title"),
  published_at: getTag(item, "pubDate"),
  description: getTag(item, "description")
}));

// ======================================
// FILTER RELEVANT NEWS
// ======================================

const relevantNews = parsedNews.filter(article => {

  const text = (
    article.title +
    " " +
    article.description
  ).toLowerCase();

  return text.includes(companyKeywords);
});

// ======================================
// LIMIT RESULTS
// ======================================

const news = relevantNews.slice(0, 5);

// ======================================
// OUTPUT
// ======================================

return [{
  json: {
    ...previous,

    news,

    news_count: news.length,

    news_summary_text: news
      .map(n =>
        `${n.title} — ${n.published_at}`
      )
      .join("\n")
      .slice(0, 3000)
  }
}];

const analysis = $json.analysis;

if (!analysis) {
  throw new Error("No company analysis found");
}

// ======================================
// ORIGINAL INPUT + ICP
// ======================================

const original = $('Code in JavaScript1').first().json;
const inputConfig = $('Code in JavaScript').first().json;

const icp = inputConfig.icp || null;

// ======================================
// NORMALIZE COMPANY SIZE
// ======================================

let companySize = analysis.company_size || null;

if (companySize) {
  const size = String(companySize).toLowerCase();

  if (
    size.includes("startup") ||
    size.includes("start-up")
  ) {
    companySize = "Startup";

  } else if (
    size.includes("small")
  ) {
    companySize = "Small";

  } else if (
    size.includes("mid-size") ||
    size.includes("mid size") ||
    size.includes("medium-sized") ||
    size.includes("medium sized")
  ) {
    companySize = "Mid-size";

  } else if (
    size.includes("enterprise") ||
    size.includes("large enterprise")
  ) {
    companySize = "Enterprise";

  } else {
    companySize = null;
  }
}

// ======================================
// NORMALIZE BUSINESS MODEL
// ======================================

let businessModel = analysis.business_model || null;

if (businessModel) {
  const model = String(businessModel).toLowerCase();

  if (model.includes("subscription")) {
    businessModel = "Subscription-based";

  } else if (model.includes("saas")) {
    businessModel = "SaaS";

  } else if (model.includes("b2b2c")) {
    businessModel = "B2B2C";

  } else if (
    model === "b2b" ||
    model.includes("business to business")
  ) {
    businessModel = "B2B";

  } else if (
    model === "b2c" ||
    model.includes("business to consumer")
  ) {
    businessModel = "B2C";

  } else if (model.includes("marketplace")) {
    businessModel = "Marketplace";

  } else {
    businessModel = null;
  }
}

// ======================================
// NORMALIZE LOCATION
// ======================================

let location = analysis.location || null;

if (location) {
  const loc = String(location).toLowerCase().trim();

  if (
    loc === "global" ||
    loc === "worldwide" ||
    loc === "international"
  ) {
    location = null;
  }
}

// ======================================
// NEWS
// ======================================

let news = [];

try {
  const newsData = $("News Parser").first().json;

  if (Array.isArray(newsData.news)) {
    news = newsData.news;
  }
} catch (error) {
  news = [];
}

// ======================================
// ARRAYS
// ======================================

const technologies = Array.isArray(analysis.technologies)
  ? analysis.technologies
  : [];

const productsServices = Array.isArray(analysis.products_services)
  ? analysis.products_services
  : [];

const growthSignals = Array.isArray(analysis.growth_signals)
  ? analysis.growth_signals
  : [];

// ======================================
// NORMALIZED ANALYSIS
// ======================================

const normalizedAnalysis = {
  company_name: analysis.company_name || null,

  description: analysis.description || null,

  industry: analysis.industry || null,

  business_model: businessModel,

  products_services: productsServices,

  target_customers: analysis.target_customers || null,

  company_size: companySize,

  location: location,

  technologies,

  growth_signals: growthSignals,

  confidence:
    typeof analysis.confidence === "number"
      ? analysis.confidence
      : null
};

// ======================================
// FINAL OUTPUT
// ======================================

return [
  {
    json: {
      ...$json,

      // Preserve user's dynamic ICP
      icp: icp,

      analysis: normalizedAnalysis,

      company_name: normalizedAnalysis.company_name,

      domain: original.domain || null,

      website: original.website || null,

      description: normalizedAnalysis.description,

      industry: normalizedAnalysis.industry,

      business_model: normalizedAnalysis.business_model,

      products_services: productsServices,

      target_customers: normalizedAnalysis.target_customers,

      company_size: normalizedAnalysis.company_size,

      location: normalizedAnalysis.location,

      technologies,

      technology_count: technologies.length,

      growth_signals: growthSignals,

      news,

      news_count: news.length,

      confidence: normalizedAnalysis.confidence
    }
  }
];

const homepage = ($json.content || "").slice(0, 5000);
const about = ($json.data || "").slice(0, 5000);

const technologies = Array.isArray($json.technologies)
  ? $json.technologies
  : [];

const news = Array.isArray($json.news)
  ? $json.news.slice(0, 3)
  : [];

return [
  {
    json: {
      ...$json,

      ai_input: {
        homepage,
        about,
        technologies,
        news
      }
    }
  }
];
